"use strict";(self.webpackChunkleia_docs=self.webpackChunkleia_docs||[]).push([[2856],{40756:e=>{e.exports=JSON.parse('{"tag":{"label":"leia","permalink":"/pr-preview/pr-10/docs/next/tags/leia","allTagsPath":"/pr-preview/pr-10/docs/next/tags","count":6,"items":[{"id":"contributing/index","title":"Contributing to LEIA","description":"Thank you for your interest in contributing to LEIA. Before diving into any individual repository, read this page. It explains how the system is structured, how services talk to each other, and how to run the full stack locally.","permalink":"/pr-preview/pr-10/docs/next/contributing/"},{"id":"introduction/index","title":"How to Use LEIA","description":"LEIA (Learning with an Educational Intelligent Assistant) is a platform that lets instructors design interactive simulations and lets students practise in realistic scenarios with AI support. A LEIA is an AI character with a role, a personality and an exercise behind it. Students talk to it, by text or by voice, and may hand in a solution that the platform grades.","permalink":"/pr-preview/pr-10/docs/next/"},{"id":"installation/installation","title":"Installation and deployment","description":"This section is meant to be a simple step-by-step guide in order to install LEIA with ease. If you are a developer who wants to extend the system, move on to the contributing section.","permalink":"/pr-preview/pr-10/docs/next/installation/"},{"id":"teachers/index","title":"LEIA for teachers","description":"This guide explains every screen, button and field that a teacher meets while designing a LEIA, running it with students and reviewing the results. Read this page first. It introduces the vocabulary and the two applications, and it tells you which page of the guide answers each task.","permalink":"/pr-preview/pr-10/docs/next/teachers/"},{"id":"tutorials/create-leia/index","title":"Quick start, your first LEIA in ten minutes","description":"Every role, including instructor. This path reuses the behaviour of an existing LEIA, so it never creates a behaviour.","permalink":"/pr-preview/pr-10/docs/next/tutorials/create-leia/"},{"id":"Team/index","title":"Team","description":"LEIA is maintained by a small team focused on product design, engineering, and documentation.","permalink":"/pr-preview/pr-10/docs/next/Team/"}],"unlisted":false}}')}}]);